// 2024-25 NBA 시즌 스탯 기반 선수 DB (per game averages)
// Fantasy Score = FGM*2 + FGA*(-1) + FTM*1.5 + FTA*(-1) + 3PTM*3 + 3PTA*(-1) + PTS*1 + REB*1.2 + AST*1.8 + ST*3 + BLK*3 + TO*(-1) + DD*3 + TD*5

export interface DBPlayer {
  id: string;
  name: string;
  nbaTeam: string;
  positions: string[];
  age: number;
  // 2024-25 per game stats
  stats: {
    GP: number; MPG: number;
    FGM: number; FGA: number;
    FTM: number; FTA: number;
    threePM: number; threePA: number;
    PTS: number; REB: number; AST: number;
    ST: number; BLK: number; TO: number;
    DD: number; TD: number;
  };
  // injury/status
  status: 'active' | 'injured' | 'out' | 'gtd';
  injuryNote?: string;
  // ADP reference
  adp: number;
}

function calcScore(s: DBPlayer['stats']): number {
  return (
    s.FGM * 2 + s.FGA * -1 +
    s.FTM * 1.5 + s.FTA * -1 +
    s.threePM * 3 + s.threePA * -1 +
    s.PTS * 1 + s.REB * 1.2 +
    s.AST * 1.8 + s.ST * 3 +
    s.BLK * 3 + s.TO * -1 +
    s.DD * 3 + s.TD * 5
  );
}

// Projection: 이전 시즌 스탯 기반 + 나이/부상 보정
function project(p: DBPlayer): number {
  let base = calcScore(p.stats);
  // 나이 보정: 27세 이하 +3%, 32세 이상 -3%
  if (p.age <= 27) base *= 1.03;
  else if (p.age >= 32) base *= 0.97;
  // 부상 이력 보정
  if (p.stats.GP < 55) base *= 0.95;
  return Math.round(base * 100) / 100;
}

